package com.bank.savings;

import java.util.logging.*;

public class MinSubarraySumDemo {
    private static final Logger log = Logger.getLogger(MinSubarraySumDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SavingsWindowAnalyzer analyzer = new SavingsWindowAnalyzer();

        int[] deposits = {2, 3, 1, 2, 4, 3}; // in thousands
        int target = 7;
        int days = analyzer.minDaysToReach(deposits, target);
        log.info(() -> "Fewest consecutive days to reach " + target + ": " + days);
    }
}

