class SavingsWindowAnalyzer {
    private static final Logger log = Logger.getLogger(SavingsWindowAnalyzer.class.getName());

    // Variable window: expand right, shrink left while valid. O(n), O(1).
    int minDaysToReach(int[] a, int target) {
        int left = 0, best = Integer.MAX_VALUE;
        long sum = 0;
        for (int right = 0; right < a.length; right++) {
            sum += a[right];                 // expand
            while (sum >= target) {          // shrink while still qualifying
                best = Math.min(best, right - left + 1);
                sum -= a[left];
                left++;
            }
        }
        if (best == Integer.MAX_VALUE) {
            log.warning(() -> "Target " + target + " never reached");
            return 0;
        }
        return best;
    }
}

